/* selectMasterMdCtBuyerChargeEntryList */ SELECT CM.COM_CODE, CM.COM_CODE AS COM_CODE_ORG, CM.COM_NAME_LOC AS COM_NAME, MS.YEAR, MS.YEAR AS YEAR_ORG, MS.KEP_DEPT, MS.KEP_DEPT AS KEP_DEPT_ORG, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = 'KRKORE0001' AND CODE = MS.KEP_DEPT) AS KEP_DEPT_NM, MS.POSITION_GROUP, MS.POSITION_GROUP AS POSITION_GROUP_ORG, MS.KEP_USER_ID, MS.KEP_USER_ID AS KEP_USER_ID_ORG, MS.KEP_USER_ID AS KEP_USER_ID_MASK, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID=MS.KEP_USER_ID) AS KEP_USER_NAME, DECODE(MS.PRIORITY,'Y','1','0') AS PRIORITY, DECODE(MS.MAIN_CLERK,'Y','1','0') AS MAIN_CLERK, MS.ITEM_GROUP FROM ICOMCMPY CM, MIS_BUYER_MNG MS WHERE CM.BUSINESS_COND = 'B' AND CM.STATUS IN ('C','R') AND MS.STATUS(+) IN ('C') AND CM.COM_CODE = MS.BUYER(+) AND TO_CHAR(TO_DATE(CM.ADD_DATE,'YYYYMMDD'),'YYYY') <= #{st_year} AND MS.YEAR(+) = #{st_year} AND MS.POSITION_GROUP <> 'PA'
AND CM.COM_CODE = #{st_com_code}
AND MS.KEP_DEPT = #{st_kep_dept}
AND MS.KEP_USER_ID = #{st_kep_user_id}
AND MS.PRIORITY = 'Y'
AND MS.MAIN_CLERK = 'Y'
ORDER BY MS.YEAR, COM_NAME_LOC, SEQ


/* selectMasterMdCtBuyerChargeEntryUserIdCheck */
SELECT
	COUNT(KEP_USER_ID) CNT
FROM MIS_BUYER_MNG
WHERE YEAR					= #{YEAR}
AND BUYER					= #{COM_CODE}
AND KEP_USER_ID				= #{KEP_USER_ID}
AND KEP_DEPT 				= #{KEP_DEPT}
AND STATUS					= 'C'


/* getMasterMdCtBuyerChargeEntryPriority */
SELECT
	COUNT(KEP_USER_ID) CNT
FROM MIS_BUYER_MNG
WHERE YEAR					= #{YEAR}
AND BUYER					= #{COM_CODE}
AND STATUS					= 'C'
AND PRIORITY				= 'Y'


/* getMasterMdCtBuyerChargeEntryMain */
SELECT
	COUNT(KEP_USER_ID) CNT
FROM MIS_BUYER_MNG
WHERE YEAR					= #{YEAR}
AND BUYER					= #{COM_CODE}
AND STATUS					= 'C'
AND MAIN_CLERK				= 'Y'


/* getMasterMdCtBuyerChargeEntryDept */
SELECT
	COUNT( DISTINCT KEP_DEPT)
FROM MIS_BUYER_MNG
WHERE YEAR					= #{YEAR}
AND BUYER					= #{COM_CODE}
AND STATUS					= 'C'

mapper.update:

/* updateMasterMdCtBuyerChargeEntryList */
UPDATE MIS_BUYER_MNG					
SET
	YEAR						= #{YEAR} 	
	,BUYER					= #{COM_CODE}
	,KEP_DEPT				= #{KEP_DEPT}
	,KEP_USER_ID			= #{KEP_USER_ID}
	,POSITION_GROUP		= #{POSITION_GROUP}
	,CHANGE_DATE			= TO_CHAR(SYSDATE, 'YYYYMMDD')
	,CHANGE_TIME			= TO_CHAR(SYSDATE, 'HH24MISS')
	,PRIORITY			= DECODE(#{PRIORITY},'1','Y','')
	,MAIN_CLERK			= DECODE(#{MAIN_CLERK},'1','Y','')
WHERE YEAR					= #{YEAR_ORG}
AND BUYER					= #{COM_CODE_ORG}
AND KEP_DEPT				= #{KEP_DEPT_ORG}
AND KEP_USER_ID			= #{KEP_USER_ID_ORG}
AND POSITION_GROUP	= #{POSITION_GROUP_ORG}
AND ITEM_GROUP			= #{ITEM_GROUP}


/* deletetMasterMdCtBuyerChargeEntryList */
UPDATE MIS_BUYER_MNG
SET STATUS					= 'O'
WHERE YEAR					= #{YEAR_ORG}
AND BUYER					= #{COM_CODE_ORG}
AND KEP_DEPT				= #{KEP_DEPT_ORG}
AND KEP_USER_ID			= #{KEP_USER_ID_ORG}
AND POSITION_GROUP	= #{POSITION_GROUP_ORG}
AND ITEM_GROUP			= #{ITEM_GROUP}
